// Migrate the old Saudi default once; an explicitly chosen currency is preserved.
if(data.meta?.currency === 'ر.س'){
  data.meta.currency = 'د.ت';
  const replaceOldCurrency = value => {
    if(Array.isArray(value)) return value.map(replaceOldCurrency);
    if(value && typeof value === 'object'){Object.keys(value).forEach(k=>value[k]=replaceOldCurrency(value[k]));return value;}
    return typeof value === 'string' ? value.replaceAll('ر.س','د.ت') : value;
  };
  data = replaceOldCurrency(data);
}
data.meta ||= {company:'شركة السريحي',currency:'د.ت',taxEnabled:false,theme:'light'};
