function product(id){return data.products.find(x=>x.id===id)}
function customer(id){return data.customers.find(x=>x.id===id)}
function supplier(id){return data.suppliers.find(x=>x.id===id)}
function vehicle(id){return data.vehicles.find(x=>x.id===id)}
function route(id){return data.routes.find(x=>x.id===id)}
function addActivity(action,detail,ref='—'){data.activity.unshift({id:uid('AC'),date:`${today()} ${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false})}`,user:'محمد السريحي',action,detail,ref});data.activity=data.activity.slice(0,100)}
function movement(productId,qty,type,from,to,ref){data.movements.unshift({id:uid('MV'),date:today(),productId,qty,type,from,to,ref});}
function productName(id){return product(id)?.name || 'صنف محذوف'}
function routeLoaded(r,pid){return (r.loaded||[]).find(x=>x.productId===pid)?.qty||0}
function routeSold(r,pid){return (r.sold||[]).filter(x=>x.productId===pid).reduce((s,x)=>s+x.qty,0)}
function routeReturned(r,pid){return (r.returned||[]).find(x=>x.productId===pid)?.qty||0}
function routeLost(r,pid){return (r.losses||[]).find(x=>x.productId===pid)?.qty||0}
function routeAvailable(r,pid){return routeLoaded(r,pid)-routeSold(r,pid)-routeReturned(r,pid)-routeLost(r,pid)}
function vehicleCurrent(vId){return data.routes.filter(r=>r.vehicleId===vId&&r.status==='مفتوحة').reduce((all,r)=>{(r.loaded||[]).forEach(x=>all[x.productId]=(all[x.productId]||0)+routeAvailable(r,x.productId));return all},{});}
function stockValue(){return data.products.reduce((s,p)=>s+p.stock*p.buy,0)}
function totalSales(period){return data.sales.filter(s=>!period||s.date>=period).reduce((a,s)=>a+s.total,0)}
function decorateNumericContent(root){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[]; let node;
  while(node=walker.nextNode()){
    const parent=node.parentElement;
    if(!parent || parent.closest('.number,.date,.date-time,[data-no-number]') || ['SCRIPT','STYLE','INPUT','TEXTAREA','SELECT','OPTION'].includes(parent.tagName)) continue;
    if(/\d/.test(node.nodeValue)) nodes.push(node);
  }
  const numeric=/[-+]?\d[\d,]*(?:\.\d+)?%?/g;
  nodes.forEach(textNode=>{
    const text=textNode.nodeValue, frag=document.createDocumentFragment(); let last=0, match;
    numeric.lastIndex=0;
    while(match=numeric.exec(text)){
      if(match.index>last) frag.append(text.slice(last,match.index));
      const span=document.createElement('span'); span.className='number'; span.dir='ltr'; span.textContent=match[0]; frag.append(span); last=match.index+match[0].length;
    }
    if(last<text.length) frag.append(text.slice(last));
    if(last) textNode.replaceWith(frag);
  });
}
function render(){
  document.querySelectorAll('.page-section').forEach(x=>x.classList.remove('active'));
  const section=document.querySelector(`#section-${activeSection}`);section.classList.add('active');
  document.querySelectorAll('.nav-item[data-section]').forEach(x=>x.classList.toggle('active',x.dataset.section===activeSection));
  document.getElementById('breadcrumb').innerHTML=`${navNames[activeSection]} <span>/</span> ${activeSection==='dashboard'?'نظرة عامة':'إدارة '+navNames[activeSection]}`;
  const renderers={dashboard:renderDashboard,products:renderProducts,warehouses:renderWarehouses,routes:renderRoutes,sales:renderSales,returns:renderReturns,purchases:renderPurchases,customers:renderCustomers,suppliers:renderSuppliers,assets:renderAssets,payments:renderPayments,expenses:renderExpenses,reports:renderReports,stocktake:renderStocktake,invoices:renderInvoices,users:renderUsers,settings:renderSettings};
  section.innerHTML=renderers[activeSection]();
  decorateNumericContent(section);
}
function pageTitle(title,sub,actions=''){return `<div class="page-title-row"><div class="page-title"><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function metric(label,value,icon,foot,trend=''){return `<div class="card metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-bottom">${trend?`<span class="${trend.startsWith('+')?'trend-up':'trend-down'}">${trend}</span> `:''}${foot}</div></div>`}
function tableSearch(placeholder='بحث...'){return `<div class="search-box"><span>⌕</span><input class="local-search" placeholder="${placeholder}" value="${esc(searchTerm)}" /></div>`}
